// Ported from the Node app's Sequelize model TransportStop (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class TransportStopConfiguration : IEntityTypeConfiguration<TransportStop>
{
    public void Configure(EntityTypeBuilder<TransportStop> builder)
    {
        builder.ToTable("transport_stops");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.RouteId).HasColumnName("route_id");
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Sequence).HasColumnName("sequence");
        builder.Property(e => e.PickupTime).HasColumnName("pickup_time").HasColumnType("nvarchar(5)").HasMaxLength(5);
        builder.HasOne(e => e.TransportRoute).WithMany(p => p.TransportStops).HasForeignKey(e => e.RouteId).OnDelete(DeleteBehavior.NoAction);
    }
}
